style.css:
@-moz-document domain("discord.com"), domain("discordapp.com") {
/* Import a Google Font (change family to try different fonts) */
  /* Apply the font everywhere useful */
  :root, body, .app-2qHmrb, .chat-3bRxxu, .container-3baos1, .markup-2BOw-j, .message-2qnXI6 {
    font-family: 'Quicksand', system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial !important;
    -webkit-font-smoothing: antialiased !important;
    text-rendering: optimizeLegibility !important;
  }

  /* optional: slightly bolder message text for readability */
  .message-2qnXI6, .markup-2BOw-j {
    font-weight: 500 !important;
  }

  /* avoid breaking fixed-width code blocks */
  code, pre, .code-1S9u2E {
    font-family: monospace !important;
  }
}
